package org.swir.phoneos.apps;
public final class AppCatalogPolicyHostTest { public static void main(String[] args) { if(!AppCatalogPolicy.matches("Swir Files","org.swir.phoneos.files","files")) throw new AssertionError(); if(!AppCatalogPolicy.matches("Swir Files","org.swir.phoneos.files","phoneos")) throw new AssertionError(); if(!AppCatalogPolicy.validPackageName("org.swir.phoneos.files")) throw new AssertionError(); if(AppCatalogPolicy.validPackageName("../bad")) throw new AssertionError(); String digest=AppCatalogPolicy.sha256(new byte[]{1,2,3}); if(digest.length()!=64||AppCatalogPolicy.shortDigest(digest).length()!=16) throw new AssertionError(); if(!"".equals(AppCatalogPolicy.shortDigest("bad"))) throw new AssertionError(); } }
